    fun forBand(band: LearningBand): List<LessonContent> = all.filter { it.band == band }
    private fun lesson(id: String, band: LearningBand, title: String, objective: String, explanation: String, words: List<LessonWord>, example: String, translation: String) =
        LessonContent(id, band, title, objective, explanation, words, example, translation)
    private fun w(english: String, dari: String, pronunciation: String) = LessonWord(english, dari, pronunciation)
